do $eflow_preservation$
declare entry record;columns text[];row_data jsonb;
begin
 if exists(select 1 from eflow_refinement_ledger_before b where not exists(select 1 from supabase_migrations.schema_migrations m where to_jsonb(m)=b.entry)) then raise exception 'Original migration history changed; rolling back'; end if;
 for entry in select * from eflow_refinement_rows_before order by schema_name,table_name loop
  columns:=entry.columns;
  execute format('select coalesce(jsonb_agg(normalized order by normalized::text),''[]''::jsonb) from (select case when $2=''projects'' and $3=''public'' and item->>''publication_state''=''draft'' then jsonb_set(item,''{publication_state}'',''"published"''::jsonb) when $2=''subtasks'' and $3=''public'' then item-''updated_at'' else item end normalized from (select (select jsonb_object_agg(key,value) from jsonb_each(to_jsonb(t)) where key=any($1)) item from %I.%I t) projected) canonical',entry.schema_name,entry.table_name) into row_data using columns,entry.table_name,entry.schema_name;
  if entry.allow_additions then
   if not row_data @> entry.rows then raise exception 'Original rows changed in %.%; rolling back',entry.schema_name,entry.table_name; end if;
  elsif row_data is distinct from entry.rows then raise exception 'Original rows changed in %.%; rolling back',entry.schema_name,entry.table_name;
  end if;
 end loop;
end $eflow_preservation$;

